import React from \"react\";
import { fireEvent, render } from \"@testing-library/react\";
import { Room } from \"matrix-js-sdk/src/models/room\";

import { Pill, PillType, pillRoomNotifLen, pillRoomNotifPos } from \"../../../../src/components/views/elements/Pill\";
import { MatrixClientPeg } from \"../../../../src/MatrixClientPeg\";
import { stubClient } from \"../../../test-utils\";

describe(\"Pill\", () => {
    beforeEach(() => stubClient());

    it(\"exports @room token helpers\", () => {
        expect(pillRoomNotifPos(\"hello @room and @room\")).toBe(6);
        expect(pillRoomNotifPos(\"hello\")).toBe(-1);
        expect(pillRoomNotifLen()).toBe(5);
    });

    it(\"renders nothing for an unrecognized target\", () => {
        const { container } = render(<Pill url=\"https://example.org/unknown\" inMessage />);
        expect(container.querySelector(\"bdi\")).toBeNull();
    });

    it(\"keeps the original URL on a message user pill\", () => {
        const url = \"https://matrix.to/#/@alice:example.org?via=example.org\";
        const { container } = render(<Pill url={url} inMessage />);
        const anchor = container.querySelector(\"bdi > a\");
        expect(anchor?.getAttribute(\"href\")).toBe(url);
        expect(anchor).toHaveClass(\"mx_Pill\", \"mx_UserPill\");
        expect(anchor?.querySelector(\".mx_Pill_linkText\")).toHaveTextContent(\"@alice:example.org\");
    });

    it(\"renders a room alias as a non-link and shows its ID on hover\", () => {
        const { container } = render(<Pill url=\"https://matrix.to/#/%23alias:example.org\" />);
        const span = container.querySelector(\"bdi > span\");
        expect(span).toHaveClass(\"mx_Pill\", \"mx_RoomPill\");
        expect(span?.querySelector(\".mx_Pill_linkText\")).toHaveTextContent(\"#alias:example.org\");
        fireEvent.mouseOver(span"'!);
        expect(container).toHaveTextContent("#alias:example.org");
    });

    it("renders @room without a URL using the current room", () => {
        const client = MatrixClientPeg.get();
        const room = new Room("!room:example.org", client, client.getUserId()!);
        const { container } = render(<Pill type={PillType.AtRoomMention} room={room} inMessage />);
        expect(container.querySelector("bdi > a")).toBeNull();
        expect(container.querySelector("bdi > span")).toHaveClass("mx_Pill", "mx_AtRoomPill");
        expect(container.querySelector(".mx_Pill_linkText")).toHaveTextContent("@room");
    });
});
EOF
